      "source": "        ack_sent = await _safe_send_json(\n            {\n                \"type\": \"chat_ack\",\n                \"request_id\": request_id,\n                \"session_id\": session_id,\n                \"status\": \"accepted\",\n            }\n        )\n        if not ack_sent:\n            # ACK 发送失败时清理已登记的活动任务和 Runtime 请求状态。\n            coordinator.finish_request(request_id, session_id=session_id)\n            await _pop_active_task(request_id, asyncio.current_task())\n            active_tasks.pop(request_id, None)\n            return\n\n        try:\n            response = (\n                await coordinator.run_chat_entry(\n                    session_id=session_id,\n                    user_id=message.user_id,\n                    prompt=message.prompt,\n                    ui_context=message.ui_context,\n                    request_id=request_id,\n                )\n                if isinstance(message, ChatStartMessage)",
