      "color": "blue",
      "source": "    async def run_chat_entry(\n        self,\n        session_id: str,\n        user_id: str,\n        prompt: str,\n        ui_context: dict[str, Any] | None = None,\n        request_id: str | None = None,\n    ) -> AgentResponse:\n        \"\"\"执行自然语言 CAX Agent 请求。\n\n        ``chat_start`` 只能进入这个入口，因而内部请求不可能同时携带机械命令。\n\n        请求先读取会话记忆并构造 ContextPack，再交给共享 Engine 路由和执行；完成后将\n        本轮对话写回短期记忆。\n        \"\"\"\n        rid = self.ensure_request(request_id, session_id=session_id)\n        try:\n            return await self._run_chat_agent_request(\n                session_id=session_id,\n                user_id=user_id,\n                prompt=prompt,\n                ui_context=ui_context,\n                request_id=rid,\n            )",
      "sourceHash": "c716c44e7e4f20ee2912123899a4d5c39eb59e21cec87199974434196558dec3",
