      "note": "这些状态来自第 52 行前采集到的局部变量。",
      "color": "blue",
      "source": "    def build(\n        self,\n        records: list[SessionMemoryRecord],\n        events: list[MemoryEvent] | None = None,\n    ) -> SessionMemory:\n        \"\"\"构造 SessionMemory。\"\"\"\n        recent_records = records[-self._recent_turn_limit :]\n        recent_turns = [self._build_turn(record) for record in recent_records]\n        active_task = self._find_active_task(records)\n        task_projection = self._projection_builder.build(events or [])\n        if task_projection is None and active_task is not None:\n            task_projection = self._projection_builder.build(\n                self._events_from_active_task(active_task)\n            )\n        return SessionMemory(\n            recent_turns=recent_turns,\n            active_task=active_task,\n            task_projection=task_projection,\n        )",
