      "color": "orange",
      "source": "    def _find_active_task(self, records: list[SessionMemoryRecord]) -> ActiveTaskMemory | None:\n        \"\"\"从后往前寻找仍需要继续推进的 active_task。\n\n        统一智能体直接处理问答和任务，最近一次响应决定当前待续接任务。\n        \"\"\"\n        for record in reversed(records):\n            active_task = self._build_active_task(record)\n            return active_task\n        return None",
      "sourceHash": "508cafccc3ad2ae3cb09940f9d9b00feca70918fbdbb1b7978ec890bf182bc9b",
